-- 182_school_url_intro_correction_181.sql
-- 数据更正（2026-11-24）：181 批按预设 id 写入，实际 1113-1118 对应院所与本批文案不符，
-- 现按库内真实单位名称重取官网简介并更正。
--
-- 安全边界：仅当 official_url 仍等于 181 批写入的错误地址时才覆盖，不触碰其他任何行；
-- 不物理删除。证据：backfill_local/out/school_intro_181_evidence.csv（更正说明见 182 段）。

UPDATE kaoyan_schools AS s
SET official_url = v.official_url,
    intro = v.intro,
    updated_at = now()
FROM (VALUES
    (1113, 'http://www.nwipb.ac.cn', 'http://www.iae.cas.cn',
     '中国科学院沈阳应用生态研究所（以下简称沈阳生态所）成立于1954年，其前身为中国科学院林业土壤研究所，1987年更为现名，2001年成为国家知识创新工程试点单位，2015年成为中国科学院“生态文明建设”领域首批特色研究所试点单位。建所以来，围绕现代农林业可持续发展和生态环境建设中亟需解决的重大科技问题，结合应用生态学发展需要，沈阳生态所在森林生态与林业生态工程、土壤生态与农业生态工程、污染生态与环境生态工程领域开展基础性、战略性和前瞻性研究，完善和创新应用生态学理论、方法和技术体系；聚焦退化生态系统恢复-重建与生态安全、黑土地保护-利用与粮食安全、污染环境治理-改善与低碳绿色发展，为东北工农业现代化和新型城镇化提供生态与环境保障，为生态文明-美丽中国建设提供科技支撑。'),
    (1114, 'http://www.isl.cas.cn', 'https://sia.cas.cn',
     '中国科学院沈阳自动化研究所成立于 1958 年，主要研究方向是机器人、智能制造与光电信息技术。研究所拥有正式员工 1400 余人，其中中国工程院院士 3 人，具有高级职称的技术人员600多人。研究所在沈阳拥有南塔街和创新路两处所区。六十多年来，沈阳自动化所在自动化科学与工程领域不断探索，为国民经济、社会发展和国家安全做出了突出贡献，获得国家、中国科学院、各部委及地方奖励 300 余项。作为中国机器人事业的摇篮，在中国机器人事业发展历史上创造了二十多个第一，引领了中国机器人技术的研究发展，成功孵化了沈阳新松机器人自动化股份有限公司、沈阳芯源微电子设备股份有限公司等 10 余家高技术企业。'),
    (1115, 'https://www.sxicc.ac.cn', 'https://dicp.cas.cn',
     '中国科学院大连化学物理研究所（以下简称“大连化物所”）创建于1949年3月。七十余载风雨兼程，大连化物所始终与祖国同行、与科学共进，坚守“国之所需、科研所向”的初心使命，传承“锐意创新、协力攻坚、严谨治学、追求一流”的精神品格，坚持以任务带学科，形成了基础前沿、应用开发、技术示范与产业化有机衔接的全链条贯通式科研体系，为国家安全与国民经济高质量发展提供了坚实有力的科技支撑。大连化物所重点学科领域包括催化化学、工程化学、化学激光和分子反应动力学，以及近代分析化学和生物技术，拥有物理学、化学、材料科学与工程、化学工程与技术四个一级学科博士学位授予权；全所设有23个研究室（部）及1个能源研究技术平台，建有能源催化转化全国重点实验室、化学反应动力学全国重点实验室等7个国家级创新平台，建成世界唯一极紫外波段自由电子激光大科学装置。'),
    (1116, 'http://www.giec.cas.cn', 'https://www.hf.cas.cn',
     '中国科学院合肥物质科学研究院（以下简称合肥物质院）是中国科学院所属大型的综合性科研机构之一，位于合肥市科学岛，面积2.65平方公里。由安光所、等离子体所、固体所、智能所、强磁场中心、核能安全所、健康所7个研究单元组成。与地方政府共建了6个成果转化平台。现有职工约2700名，领军人才如两院院士、海内外高层次人才、国家杰出青年基金获得者、国家重点研发计划首席科学家、关键技术人才等300余人。设有6个博士后流动站、18个博士点和21个硕士点，在学研究生约3100名。拥有30多个国家或省部级重点实验室和研究中心，以及10多个大型实验平台。'),
    (1117, 'https://gibh.cas.cn', 'http://www.fjirsm.ac.cn',
     '中国科学院福建物质结构研究所（简称福建物构所）由我国著名科学家、教育家卢嘉锡院士于1960年创建，是中国科学院优秀研究所。研究所立足“注重原创基础研究，加强变革创新，促进成果转移转化”战略定位，发挥结构化学、催化化学、晶体材料和激光技术等学科优势，促进新材料、新能源、先进制造装备等领域的核心关键技术突破，有重点地开展前沿科学研究、产业关键技术研发、技术集成创新、工程化示范和科技成果转移转化工作，经过60多年发展，取得了以“中国牌”BBO、LBO等一系列光学晶体为代表的一批具有引领国际领先水平的研究成果，获得国家科技三大奖及中国科学院科技进步特等奖等重要科技成果和奖励260余项，培植了福晶科技股份有限公司、青岛海泰光电科技、福建中科光芯等多家高科技企业，已成为在国际上具有重要影响力的结构化学、新材料与器件集成与应用的综合研究基地。'),
    (1118, 'https://www.siat.ac.cn', 'https://qdio.cas.cn',
     '中国科学院海洋研究所始建于1950年8月1日，是新中国成立的第一个专业从事海洋科学研究的综合性科研机构，是我国海洋科学的发源地，第一任所长是童第周。建所70多年来，海洋所在我国海洋基础研究、应用基础研究领域做出了许多奠基性和开创性的工作，引领了我国海洋科学的发展，目前仍然是我国规模最大、实力最强的综合性海洋研究机构之一。海洋研究所拥有古镇口园区、南海路园区、科考船码头基地“两园区一基地”，建有实验海洋生物学实验室、海洋生态与环境科学实验室、海洋环流与波动实验室、海洋地质与环境实验室、海洋环境腐蚀与生物污损实验室、海洋生物分类与系统演化实验室等6个实验室，深海极端环境与生命过程研究中心、海洋生物智造产业创新中心、海洋人工智能研究中心、海洋先进传感技术研发中心等4个交叉研究群组。')
) AS v(id, wrong_url, official_url, intro)
WHERE s.id = v.id
  AND s.official_url = v.wrong_url;
